function throat(voiced){return svg(`<path d="M85 40q-10 58 20 82l-4 90m95-172q10 58-20 82l4 90" stroke="#d2a78c" stroke-width="26" fill="none"/><path d="M115 260l-16-71q-5-18 6-20l14 32-7-69q-1-17 11-15l12 64-1-78q0-16 12-12l6 78 7-62q4-14 14-8l-1 76 15-35q8-16 18-7l-18 84-28 43Z" fill="#e6ba99" stroke="#b68f77" stroke-width="3"/>${voiced?'<g class="voice-wave"><path d="M53 117q-20 27 0 53m190-53q20 27 0 53M35 105q-29 40 0 77m226-77q29 40 0 77" stroke="#6ca48a" stroke-width="6" fill="none"/></g>':''}`,'0 0 300 300','throat',voiced?'Mão na garganta: vibra':'Mão na garganta: sem vibração');}
function cMouth(k,side=false,still=false,transition=0,vowel='A'){
 if(ADVKEYS.includes(k))return advancedMouth(k,side,still,transition,vowel);
 if(STOPKEYS.includes(k))return stopMouth(k,side,still,transition,vowel);
 const d=CONSONANTS[k],nasal=d.kind.startsWith('nasal'),lip=d.kind==='lip-teeth',up=d.kind==='lateral'||d.kind==='nasal-tongue',m=LETTERS[vowel].mouth,t=transition;
 const rx=(d.kind==='nasal-lips'?48:lip?46:up?43:52)*(1-t)+m.rx*t,ry=(d.kind==='nasal-lips'?0:lip?12:up?29:8)*(1-t)+m.ry*t;
 const motion=still?'':'mouth-opening',airClass=still?'':'air';
 if(!side){const y=205,teethY=(lip?211:up?182:199)*(1-t)+(y-m.ry*.6)*t,tongueY=(up?184:221)*(1-t)+(y+m.ry*.5)*t;
 return svg(`<path d="M86 80Q150 45 214 80L227 170Q225 270 150 280Q75 270 73 170Z" fill="#f0c6a9"/><path d="M112 96q11-5 20 0m36 0q10-5 20 0" stroke="#8f6e5c" stroke-width="4" fill="none" stroke-linecap="round"/><path d="M150 115l-8 31q8 7 16 0" fill="none" stroke="#c18e72" stroke-width="4"/><g class="${d.kind==='nasal-lips'?'':motion}"><ellipse cx="150" cy="205" rx="${rx+8}" ry="${ry+7}" fill="#c97974"/>${ry>1?`<ellipse cx="150" cy="205" rx="${rx}" ry="${ry}" fill="#653e43"/><path d="M${150-rx*.7} ${teethY-7}Q150 ${teethY-3} ${150+rx*.7} ${teethY-7}v12Q150 ${teethY+8} ${150-rx*.7} ${teethY+5}Z" fill="#fffbee"/>${up?`<path d="M126 ${205+ry*.7}Q125 ${tongueY} 145 ${tongueY}Q169 ${tongueY} 174 ${205+ry*.7}Z" fill="#df9294"/>`:''}`:'<path d="M105 205q45 7 90 0" stroke="#915751" stroke-width="3" fill="none"/>'}</g>${nasal&&t<.4?`<path d="M159 148q52-12 62-44m-61 53q52-3 73-35" fill="none" stroke="#5babc2" stroke-width="4" class="${airClass}"/>`:''}${d.kind==='lateral'&&t<.4?`<path d="M113 204l-17 32m88-32 17 32" stroke="#5babc2" stroke-width="4" class="${airClass}" fill="none"/>`:''}`,'30 40 240 255','mouth-svg',`Boca de frente ${k}`);}
 const gap=d.kind==='nasal-lips'?0:lip?15:up?36:15;
 return svg(`<path d="M58 42Q145 5 197 57L200 107L236 141L215 150L218 175L230 184L218 ${190+gap}L209 247Q198 287 164 297L148 320H53Z" fill="#f0c6a9" stroke="#d6a58a" stroke-width="3"/><path d="M85 130Q146 104 199 160L215 176L218 185L209 ${187+gap}Q178 244 113 239L94 292L66 276L86 204Z" fill="#fff9ed"/><path d="M93 111Q150 68 198 123L216 141" stroke="#fff4df" stroke-width="16" fill="none"/><path d="M89 132Q150 108 199 165L214 175" stroke="#ad776d" stroke-width="8" fill="none"/><path d="M194 166v22h14v-17" fill="white" stroke="#b5b1a4" stroke-width="2"/><path d="M85 245Q93 190 153 218Q181 ${up?175:221} ${up?193:201} ${up?173:215}L195 239Q140 266 106 270Z" fill="#df9294" stroke="#be777e" stroke-width="3"/><path d="M213 179l17 6M212 ${193+gap}l18 ${lip?-22:-3}" stroke="#c97974" stroke-width="8" stroke-linecap="round"/>${nasal?`<path d="M103 239Q83 169 111 118Q159 89 202 130L271 139" stroke="#5babc2" stroke-width="5" fill="none" class="${airClass}"/><path d="M260 131l13 8-13 6" stroke="#5babc2" stroke-width="4" fill="none"/><text x="239" y="113" class="anatomy-label">NARIZ</text>`:`<path d="M101 232Q118 185 172 196L280 200" stroke="#5babc2" stroke-width="5" fill="none" class="${airClass}" ${up?'stroke-opacity=".65"':''}/><path d="M269 193l13 7-13 7" stroke="#5babc2" stroke-width="4" fill="none"/><text x="218" y="244" class="anatomy-label">${up?'PELOS LADOS':'AR PELA BOCA'}</text>`}<text x="78" y="311" class="anatomy-label">${d.kind==='nasal-lips'?'LÁBIOS FECHADOS':up?'LÍNGUA TOCA EM CIMA':lip?'DENTE + LÁBIO':'PASSAGEM ESTREITA'}</text>`,'15 0 305 335','mouth-svg',`Boca de lado ${k}: ${nasal?'ar pelo nariz':up?'ar pelos lados':'ar pela boca'}`);
}
function cHeading(title){return `<div class="lesson-head"><div><p class="eyebrow" style="color:${cData().color}">${cKey()==='CH'?'CH / X':'LETRA '+cKey()} · ${CSTEPS[cstate.step]}</p><h2>${title}</h2></div><span class="pill">${cstate.letter+1} / ${currentKeys().length}</span></div>`;}
function cWordTiles(){const w=cData().words[0];return [...w[1]].reverse().concat('MI');}
function cRender(){clearTimeout(sequenceTimer);cslots=Array(cData().words[0][1].length).fill(null);cselected=null;$('#crumb').textContent=clevel===4?'NÍVEL 4 / NOVOS SONS E ESCRITAS':clevel===3?'NÍVEL 3 / SONS RÁPIDOS':'NÍVEL 2 / SONS QUE CONTINUAM';$('#next').disabled=!cAllowed();$('#back').disabled=false;$('#next').textContent='AVANÇAR →';$('#progress').innerHTML=state.page==='cLesson'?CSTEPS.map((_,i)=>`<span class="dot ${i===cstate.step?'active':''}"></span>`).join('')+`<span class="counter">${cstate.step+1} / 9</span>`:`<span class="pill">NÍVEL ${clevel} · ${currentKeys().join(' ')}</span>`;
 const k=cKey(),d=cData();$('#frame').style.setProperty('--vowel',d.color);let html='';
 if(state.page==='cMap')html=`<div class="map-title"><div><p class="eyebrow">NÍVEL 0${clevel} · A TRILHA CONTINUA</p><h2>${clevel===4?'Novos sons. Novas descobertas.':clevel===3?'Prepare. Solte. Junte!':'Estique o som. Junte as letras.'}</h2></div><span class="pill">${currentKeys().filter(cDone).length} DE ${currentKeys().length} DESCOBERTAS</span></div><div class="trail c-trail">${currentKeys().map((x,i)=>`<div class="trail-item" style="--c:${CONSONANTS[x].color}"><button class="letter-stop" data-cletter="${i}">${x}</button><p>${cDone(x)?'✦ DESCOBERTA!':'VAMOS OUVIR'}</p></div>`).join('')}</div><div class="map-bottom">${owl()}<span>${clevel===4?'Olhe as letras.<br>Escute cada palavra!':clevel===3?'Um som rápido…<br>E a vogal vem logo depois!':'Um som pode continuar…<br>E abraçar uma vogal!'}</span><button class="action" style="margin-left:auto" data-action="map">REVER VOGAIS</button></div>`;
 if(state.page==='cFinish')html=`<section class="finish">${owl()}<p class="eyebrow">NÍVEL ${clevel} · NOVAS DESCOBERTAS</p><h1>${clevel===4?'Que aventura de descobertas!':'Os sons viraram palavras!'}</h1><p class="subtitle">${currentKeys().join(" · ")}</p><div class="button-row"><button class="action listen" data-caction="map">REVER A TRILHA</button><button class="action" data-action="map">REVER AS VOGAIS</button>${clevel===2?'<button class="action listen" data-caction="enter3">NÍVEL 3 →</button>':clevel===3?'<button class="action listen" data-caction="enter4">NÍVEL 4 →</button>':''}</div><p class="smallnote">${currentKeys().filter(cDone).length} de ${currentKeys().length} letras concluídas.<br>${clevel===4?"Fim desta aula · Níveis 1 a 4. Volte às trilhas sempre que quiser.":clevel===3?"O Nível 4 já está disponível.":"O Nível 3 já está disponível."}</p></section>`;
 if(state.page==='cLesson'){
 const titles=[k==='CH'?'Duas letras, um som!':'Olá, letra '+k+'!','Que som é esse?','Olhe como a boca faz.','Agora é a sua vez!',isBrief(k)?'Solte o som na vogal.':'Um abraço de sons.','Vamos formar palavras?','Qual começa com este som?','Qual boca faz este som?','Junte as sílabas.'];html=cHeading(titles[cstate.step]);
 if(cstate.step===0)html+=`<div class="lesson-body intro-letter"><div class="giant" style="font-size:${k.length>1?240:350}px">${k}${prefs.lower?`<span class="lower">${k.toLowerCase()}</span>`:''}</div><div><div class="side-mascot">${owl()}<div class="speech">${k==='CH'?'DUAS LETRAS,<br>UM SOM:':'ESTA É<br>A LETRA'} <b style="color:${d.color}">${k}</b>!</div></div><button class="action listen" data-say="${k==='CH'?'C e H juntas representam um som. Como no começo de chave.':'Esta é a letra '+d.name+'.'}" style="margin-top:24px">OUVIR A LUMI</button>${d.rule?`<p class="smallnote">${d.rule}</p>`:''}</div></div>`;
 if(cstate.step===1)html+=`<div class="lesson-body sound-layout"><div class="sound-art">${cArt(d.scene)}</div><div><div class="sound-text">${d.sound}</div><p class="sound-guide">${d.cue}</p><button class="action listen" data-phoneme="${k}">${recordings.has(k)?'OUVIR O SOM':'IMITAR COM A PROFESSORA'}</button><p class="smallnote">${recordings.has(k)?'A voz da professora acompanha o desenho.':'Olhe o desenho. A professora faz o som.'}</p></div></div>`;
 if(cstate.step===2)html+=`<div class="c-mouth-layout"><div class="mouth-card"><span>DE FRENTE</span>${cMouth(k)}</div><div class="mouth-card"><span>DE LADO</span>${cMouth(k,true)}</div><div class="vibration">${throat(d.voiced)}<b>${d.variableVoice?'PODE VARIAR':d.voiced?'VIBRA':'SEM VIBRAÇÃO'}</b>${d.pair?`<button class="action" data-pair="${d.pair}">COMPARAR ${d.pair}</button>`:'<p class="smallnote">MÃO NA GARGANTA</p>'}</div></div><div class="mouth-tip"><span>${d.tip}</span><button class="action" data-caction="imitate">AGORA VOCÊ →</button></div>`;
 if(cstate.step===3)html+=`<div class="lesson-body mirror-layout"><div class="mirror">${cMouth(k)}</div><div class="mirror-copy"><p class="eyebrow">OLHE · IMITE · SINTA</p><h2>${d.kind.startsWith('nasal')?'PELO NARIZ!':d.voiced?'SINTA A VOZ!':'DEIXE O AR SAIR!'}</h2><p>${d.tip}</p><button class="action listen" data-phoneme="${k}" style="margin-top:24px">VAMOS FAZER O SOM</button></div></div>`;
 if(cstate.step===4){const v=familyVowels()[cstate.vowel];html+=`<div class="family-tabs">${familyVowels().map((x,i)=>`<button class="blend-tag ${i===cstate.vowel?'selected':''}" data-cvowel="${i}">${k}<span style="color:${LETTERS[x].color}">${x}</span></button>`).join('')}<button class="action" data-caction="sequence">TODAS →</button></div><div class="c-fusion"><div class="blend-letters" id="c-fusion"><span style="color:${d.color}">${k}</span><span style="color:${LETTERS[v].color}">${v}</span></div><div id="c-transition">${cMouth(k)}</div></div><div class="button-row" style="justify-content:center"><button class="action listen" data-caction="fuse">JUNTAR ${k} + ${v}</button><button class="action" data-say="${k+v}">OUVIR ${k+v}</button></div><p class="smallnote" style="text-align:center">${recordings.has(k+v)?'Junção gravada pela professora.':isBrief(k)?'Feche, solte e entre na vogal. O primeiro som é breve.':'A professora prolonga o som e junta, sem pausa.'}</p>`;}
 if(cstate.step===5){const w=d.words[cstate.word];html+=`${k==='CH'?'<p class="smallnote" style="text-align:center">CHAVE E XÍCARA: MESMO SOM INICIAL. O X PODE TER OUTROS SONS.</p>':''}<div class="c-word-nav">${d.words.map((x,i)=>`<button class="action ${i===cstate.word?'listen':''}" data-cword="${i}">${x[0]}</button>`).join('')}</div><div class="c-word-layout"><div class="word-picture">${cArt(w[2])}</div><div><div class="syllable-word" id="c-word">${w[1].map((s,i)=>`<button data-say="${s}" style="color:${i%2?'#5d83b6':d.color}">${s}</button>`).join('')}</div><div class="button-row"><button class="action listen" data-caction="word">JUNTAR E OUVIR</button><button class="action" data-say="${w[0]}">OUVIR A PALAVRA</button></div></div></div>`;}
 if(cstate.step===6){const others=currentKeys().filter(x=>x!==k);const ids=[d.words[0],CONSONANTS[others[0]].words[0],CONSONANTS[others[2]].words[0]];const offset=cstate.letter%3;const choices=ids.slice(offset).concat(ids.slice(0,offset));html+=`<div class="button-row" style="justify-content:center;margin-top:20px"><button class="action listen" data-phoneme="${k}">OUVIR / IMITAR ${k}</button></div><div class="choices c-choices">${choices.map(w=>`<button class="choice" data-canswer="${w[0]}" aria-label="${w[0]}">${cArt(w[2])}</button>`).join('')}</div><div class="feedback" role="status">${cprogress[k+'-initial']?'✦ SOM DESCOBERTO!':'TOQUE EM UMA FIGURA.'}</div>`;}
 if(cstate.step===7){const choices=[k,...(d.kind==='stop-lips'?['F','L']:d.kind==='stop-tongue'?['M','F']:d.kind==='nasal-lips'?['F','L']:d.kind==='lip-teeth'?['M','L']:d.kind==='groove'?['M','F']:['M','F'])];const ordered=cstate.letter%2?choices.reverse():[choices[1],choices[0],choices[2]];html+=`<div class="button-row" style="justify-content:center;margin-top:16px"><button class="action listen" data-phoneme="${k}">OUVIR / IMITAR ${k}</button></div><div class="choices c-choices">${ordered.map(x=>`<button class="choice" data-cmouth="${x}" aria-label="Boca de ${x}">${cMouth(x,true,true)}</button>`).join('')}</div><div class="feedback" role="status">${cprogress[k+'-mouth']?'✦ VOCÊ OBSERVOU A BOCA!':d.tip}</div>`;}
 if(cstate.step===8){const w=d.words[0],tiles=cWordTiles();html+=`<div class="join-layout c-join"><div class="join-prompt">${cArt(w[2])}<button class="action listen" data-say="${w[0]}">OUVIR A PALAVRA</button><p class="smallnote">${w[0]}</p></div><div><div class="slots">${w[1].map((_,i)=>`<button class="slot c-slot" data-cslot="${i}" aria-label="Espaço ${i+1}"></button>`).join('')}</div><div class="tiles">${tiles.map((s,i)=>`<button class="tile c-tile" draggable="true" data-ctile="${i}">${s}</button>`).join('')}</div><p class="smallnote" style="text-align:center">ARRASTE OU TOQUE NA SÍLABA E NO ESPAÇO.</p></div></div><div class="feedback" role="status">${cprogress[k+'-join']?'✦ PALAVRA MONTADA!':'PODE EXPERIMENTAR E TROCAR.'}</div>`;}
 }$('#content').innerHTML=html;
}
function cAward(type,ok,button,message){if(ok){cprogress[cKey()+'-'+type]=true;saveC();}feedback(ok,button,message);}
function cFuse(auto=false){const k=cKey(),v=familyVowels()[cstate.vowel],token=renderId;$('#c-fusion')?.classList.add('merged');if(recordings.has(k+v))playRecorded(k+v);else if(!auto)toast(isBrief(k)?'Prepare a boca e solte o som breve diretamente em '+v+'. Não alongue '+k+'.':'Alongue /'+k.toLowerCase()+'/ e deslize até '+v+', sem dizer o nome da letra.');const start=performance.now(),duration=prefs.speed==='3.6'?3200:2300;function frame(now){if(renderId!==token||!$('#c-transition'))return;const t=prefs.reduce?1:Math.min((now-start)/duration,1);$('#c-transition').innerHTML=t<1?cMouth(k,false,true,t*t*(3-2*t),v):mouth(v,false,true,LETTERS[v].mouth);if(t<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);}
function cSequence(i=0){cGo('cLesson',{step:4,vowel:i});cFuse(true);if(i<familyVowels().length-1)sequenceTimer=setTimeout(()=>cSequence(i+1),4600);}
function cPlace(tile,slot){const tiles=cWordTiles();if(!Number.isInteger(tile)||tile<0||tile>=tiles.length||slot<0||slot>=cslots.length)return;cslots=cslots.map(x=>x===tile?null:x);cslots[slot]=tile;cselected=null;cUpdateSlots();if(cslots.every(x=>x!==null)){const target=cData().words[0][0],answer=cslots.map(i=>tiles[i]).join(''),ok=target===answer;cAward('join',ok,null,ok?'ISSO! '+target+'!':'VAMOS TROCAR A ORDEM?');if(ok)speak(target);}}
function cUpdateSlots(){const tiles=cWordTiles();document.querySelectorAll('[data-cslot]').forEach((el,i)=>{el.textContent=cslots[i]===null?'':tiles[cslots[i]];});document.querySelectorAll('[data-ctile]').forEach(el=>{el.classList.toggle('used',cslots.includes(+el.dataset.ctile));el.classList.remove('selected');});}
$('#content').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.cletter!==undefined)cGo('cLesson',{letter:+b.dataset.cletter,step:0,vowel:0,word:0});if(b.dataset.cvowel!==undefined)cGo('cLesson',{vowel:+b.dataset.cvowel});if(b.dataset.cword!==undefined)cGo('cLesson',{word:+b.dataset.cword});if(b.dataset.canswer){const ok=b.dataset.canswer===cData().words[0][0];cAward('initial',ok,b,ok?'ISSO! '+b.dataset.canswer+' COMEÇA COM '+cKey()+'.':'OUÇA '+b.dataset.canswer+'. VAMOS TENTAR DE NOVO?');speak(b.dataset.canswer);}if(b.dataset.cmouth){const ok=b.dataset.cmouth===cKey();cAward('mouth',ok,b,ok?'ISSO! '+cData().tip:'OLHE MAIS UMA VEZ: '+cData().tip);}if(b.dataset.ctile!==undefined){cselected=+b.dataset.ctile;document.querySelectorAll('[data-ctile]').forEach(el=>el.classList.toggle('selected',el===b));}if(b.dataset.cslot!==undefined){const i=+b.dataset.cslot;if(cselected!==null)cPlace(cselected,i);else{cslots[i]=null;cUpdateSlots();}}if(b.dataset.pair){const other=b.dataset.pair;$('#tip-text').innerHTML=`<div class="pair-compare">${[cKey(),other].map(x=>`<div><b style="font-size:38px">${x}</b>${cMouth(x)}${throat(CONSONANTS[x].voiced)}<p>${CONSONANTS[x].voiced?'VIBRA':'SEM VIBRAÇÃO'}</p><button class="action" data-pair-audio="${x}">IMITAR ${x}</button></div>`).join('')}</div><p>Mesma posição da boca. Sinta a diferença na garganta.</p>`;$('#tips').showModal();}switch(b.dataset.caction){case'enter':cEnter();break;case'enter3':enter3();break;case'enter4':enter4();break;case'map':cGo('cMap');break;case'imitate':cGo('cLesson',{step:3});break;case'fuse':cFuse();break;case'sequence':cSequence();break;case'word':{const w=cData().words[cstate.word],token=renderId;$('#c-word').classList.add('joined');sequenceTimer=setTimeout(()=>{if(token===renderId)speak(w[0]);},prefs.reduce?0:1400);break;}}});
$('#tips').addEventListener('click',e=>{const b=e.target.closest('[data-pair-audio]');if(b)playRecorded(b.dataset.pairAudio);});
$('#content').addEventListener('dragstart',e=>{const t=e.target.closest('[data-ctile]');if(t){e.dataTransfer.setData('text/plain',t.dataset.ctile);e.dataTransfer.effectAllowed='move';}});
$('#content').addEventListener('dragover',e=>{if(e.target.closest('[data-cslot]'))e.preventDefault();});$('#content').addEventListener('drop',e=>{const s=e.target.closest('[data-cslot]');if(s){e.preventDefault();const v=e.dataTransfer.getData('text/plain');if(/^\d+$/.test(v))cPlace(+v,+s.dataset.cslot);}});
$('#content').addEventListener('pointerdown',e=>{const t=e.target.closest('[data-ctile]');if(t&&e.pointerType!=='mouse')cdrag={tile:+t.dataset.ctile,x:e.clientX,y:e.clientY};});$('#content').addEventListener('pointerup',e=>{if(!cdrag)return;const d=cdrag;cdrag=null;const hit=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-cslot]');if(hit&&Math.hypot(e.clientX-d.x,e.clientY-d.y)>15)cPlace(d.tile,+hit.dataset.cslot);});$('#content').addEventListener('pointercancel',()=>cdrag=null);
$('#c-menu').innerHTML=CKEYS.map((k,i)=>`<button data-cjump="${i}" style="--c:${CONSONANTS[k].color}">${k}</button>`).join('');$('#c-menu').onclick=e=>{const b=e.target.closest('[data-cjump]');if(b){$('#teacher').close();clevel=2;cGo('cLesson',{letter:+b.dataset.cjump,step:0,vowel:0,word:0});}};$('#go-level2').onclick=()=>{$('#teacher').close();cEnter(true);};
$('#record-key').innerHTML+=[...CKEYS,...STOPKEYS,...ADVKEYS].flatMap(k=>[k,...familyVowels(k).map(v=>k+v)]).map(k=>`<option value="${k}">${CONSONANTS[k]?k+' (som puro)':k+(isBrief(k.startsWith('CH')?'CH':k[0])?' (soltura + vogal)':' (junção contínua)')}</option>`).join('');
const vowelHelp=$('#help').onclick;$('#help').onclick=()=>{if(!state.page.startsWith('c')){vowelHelp();return;}$('#tip-text').textContent=state.page==='cLesson'?cData().teacher+' '+(clevel===4?'Nesta etapa, observe a combinação de letras. C/G ficam restritos a A, O, U. CH/X exemplifica o mesmo som em palavras escolhidas, sem generalização. As bocas são esquemas simplificados. Use gravações para os fonemas e a fala do navegador para sílabas e palavras. ':clevel===3?'O desenho desacelera o gesto, não a duração do fonema. Observe o fechamento seguido da soltura. Na família, grave a consoante breve entrando diretamente na vogal; não acrescente ê. O jogo de boca usa posições diferentes, pois P/B e T/D não se distinguem só pela aparência. A voz sintética pode seguir a variante regional para TI/DI. ': ['Apresente o nome da letra; diferencie-o do som puro na próxima tela.','A associação é uma brincadeira. Use sua voz para o fonema, sem acrescentar vogal.','Esquemas didáticos simplificados. Em L, a seta lateral é uma projeção do ar que contorna os lados da língua; não passa através dela.','Peça uma imitação confortável. O espelho é um desenho, sem câmera.','Escolha cada vogal ou toque em TODAS. Grave MA, ME etc. como uma fusão contínua; a voz sintética só lê a sílaba pronta. E/O das famílias usam modelo fechado; palavras podem ter som aberto.','Toque nas sílabas para ouvir; JUNTAR reúne a palavra. Algumas palavras exigem mediação de sons que ainda serão ensinados.','Nomeie as figuras oralmente. O foco é identificar o som inicial.','Observe a posição e o caminho do ar, não apenas a abertura. F/V e S/Z são contrastados na tela da boca; aqui as alternativas têm posições diferentes.','Arraste ou toque numa sílaba e depois num espaço. O nome escrito funciona como apoio. Para aumentar o desafio, cubra-o durante a atividade.'][cstate.step]):'A aula contém quatro níveis: vogais; consoantes contínuas; consoantes rápidas; C/G com A/O/U, J, R inicial e CH/X. O menu da professora permite acesso direto. O avanço regular exige os jogos. As gravações e o progresso ficam neste navegador; limpar os dados do navegador pode apagá-los.';$('#tips').showModal();};


// Oclusivas: o gesto é desacelerado, mas a soltura do som permanece breve.
function stopMouth(k,side=false,still=false,transition=0,vowel='A'){
 const d=CONSONANTS[k],labial=d.kind==='stop-lips';
 function shape(open){
  if(!side){const ry=labial?(open?25:0):(open?34:24);return `<path d="M86 80Q150 45 214 80L227 170Q225 270 150 280Q75 270 73 170Z" fill="#f0c6a9"/><path d="M112 96q11-5 20 0m36 0q10-5 20 0M150 115l-8 31q8 7 16 0" stroke="#b48a70" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse cx="150" cy="205" rx="54" ry="${ry+7}" fill="#c97974"/>${ry?`<ellipse cx="150" cy="205" rx="46" ry="${ry}" fill="#653e43"/><path d="M118 184h64v12h-64Z" fill="#fffbee"/>${!labial?`<path d="M125 222Q130 ${open?221:184} 150 ${open?221:184}Q169 ${open?221:184} 175 222Z" fill="#df9294"/>`:''}`:'<path d="M106 205q44 5 88 0" stroke="#915751" stroke-width="3" fill="none"/>'}${open?'<path d="M212 207h25m-21-14 20-8m-20 34 20 8" stroke="#5babc2" stroke-width="4" fill="none"/>':''}`;}
  const gap=open?31:labial?0:27;
  return `<path d="M58 42Q145 5 197 57L200 107L236 141L215 150L218 175L230 184L218 ${190+gap}L209 247Q198 287 164 297L148 320H53Z" fill="#f0c6a9" stroke="#d6a58a" stroke-width="3"/><path d="M85 130Q146 104 199 160L215 176L218 185L209 ${187+gap}Q178 244 113 239L94 292L66 276L86 204Z" fill="#fff9ed"/><path d="M89 132Q150 108 199 165L214 175" stroke="#ad776d" stroke-width="8" fill="none"/><path d="M194 166v22h14v-17" fill="white" stroke="#b5b1a4" stroke-width="2"/><path d="M85 245Q93 190 153 218Q181 ${!labial&&!open?175:222} ${!labial&&!open?193:201} ${!labial&&!open?173:216}L195 239Q140 266 106 270Z" fill="#df9294" stroke="#be777e" stroke-width="3"/><path d="M213 179l17 6M212 ${193+gap}l18-3" stroke="#c97974" stroke-width="8" stroke-linecap="round"/>${open?'<path d="M110 212Q150 184 190 197L282 202m-13-8 13 8-14 7" stroke="#5babc2" stroke-width="5" fill="none"/>':''}<text x="64" y="310" class="anatomy-label">${open?'SOLTA O AR PELA BOCA':labial?'LÁBIOS FECHAM':'LÍNGUA FECHA EM CIMA'}</text>`;
 }
 const view=side?'15 0 305 335':'30 40 240 255';
 if(transition>0){
  // Primeiro fecha; a soltura é rápida e entra imediatamente na vogal.
  if(transition<.58)return svg(shape(false),view,'mouth-svg',`${k}: fechamento`);
  if(transition<.72)return svg(shape(true),view,'mouth-svg',`${k}: soltura breve`);
  const t=Math.min((transition-.72)/.28,1),m=LETTERS[vowel].mouth;
  return mouth(vowel,false,true,{rx:46+(m.rx-46)*t,ry:25+(m.ry-25)*t,tongue:m.tongue});
 }
 return svg(still?shape(false):`<g class="stop-closed">${shape(false)}</g><g class="stop-release">${shape(true)}</g>`,view,'mouth-svg',`${k}: ${labial?'lábios':'língua'} fecham e soltam o ar`);
}
$('#stop-menu').innerHTML=STOPKEYS.map((k,i)=>`<button data-stopjump="${i}" style="--c:${CONSONANTS[k].color}">${k}</button>`).join('');
$('#stop-menu').onclick=e=>{const b=e.target.closest('[data-stopjump]');if(b){$('#teacher').close();clevel=3;cGo('cLesson',{letter:+b.dataset.stopjump,step:0,vowel:0,word:0});}};
$('#go-level3').onclick=()=>{$('#teacher').close();enter3(true);};


function advancedMouth(k,side=false,still=false,transition=0,vowel='A'){
 const d=CONSONANTS[k],stop=d.kind==='stop-back',hush=d.kind==='hush';
 const view=side?'15 0 305 335':'30 40 240 255';
 function shape(open){
  if(!side){const rx=hush?30:44,ry=hush?20:open?32:24;return `<path d="M86 80Q150 45 214 80L227 170Q225 270 150 280Q75 270 73 170Z" fill="#f0c6a9"/><path d="M112 96q11-5 20 0m36 0q10-5 20 0M150 115l-8 31q8 7 16 0" stroke="#b48a70" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse cx="150" cy="205" rx="${rx+9}" ry="${ry+8}" fill="#c97974"/><ellipse cx="150" cy="205" rx="${rx}" ry="${ry}" fill="#653e43"/><path d="M${150-rx*.7} ${205-ry*.7}h${rx*1.4}v10h-${rx*1.4}Z" fill="#fffbee"/><path d="M125 224q25-${stop&&!open?26:10} 50 0" fill="#df9294"/>${open||!stop?`<path d="M206 206h40m-33-12 29-8m-29 33 29 8" stroke="#5babc2" stroke-width="4" fill="none" class="${still?'':'air'}"/>`:''}`;}
  return `<path d="M58 42Q145 5 197 57L200 107L236 141L215 150L218 175L${hush?240:230} 184L218 222L209 247Q198 287 164 297L148 320H53Z" fill="#f0c6a9" stroke="#d6a58a" stroke-width="3"/><path d="M85 130Q146 104 199 160L215 176L218 185L209 218Q178 244 113 239L94 292L66 276L86 204Z" fill="#fff9ed"/><path d="M89 132Q150 108 199 165L214 175" stroke="#ad776d" stroke-width="8" fill="none"/><path d="M194 166v22h14v-17" fill="white" stroke="#b5b1a4" stroke-width="2"/><path d="M85 245Q90 ${stop&&!open?126:181} 127 ${stop&&!open?128:208}Q161 ${hush?170:213} 193 ${hush?186:219}L195 239Q140 266 106 270Z" fill="#df9294" stroke="#be777e" stroke-width="3"/><path d="M213 179l${hush?27:17} 6M212 224l${hush?27:18}-4" stroke="#c97974" stroke-width="8" stroke-linecap="round"/>${open||!stop?`<path d="M100 235Q111 169 165 186L280 202m-12-8 13 8-13 7" stroke="#5babc2" stroke-width="5" fill="none" class="${still?'':'air'}"/>`:''}<text x="51" y="309" class="anatomy-label">${stop?(open?'LÍNGUA SOLTA ATRÁS':'LÍNGUA FECHA ATRÁS'):hush?'AR CONTÍNUO · BIQUINHO':'AR · PONTA RELAXADA'}</text>`;
 }
 if(transition>0){const onset=stop?.6:0,release=stop?.72:0;if(stop&&transition<onset)return svg(shape(false),view,'mouth-svg',k+': fechamento posterior');if(stop&&transition<release)return svg(shape(true),view,'mouth-svg',k+': soltura');const t=stop?(transition-release)/(1-release):transition,m=LETTERS[vowel].mouth;return mouth(vowel,false,true,{rx:(hush?30:44)+(m.rx-(hush?30:44))*t,ry:22+(m.ry-22)*t,tongue:m.tongue});}
 return svg(stop&&!still?`<g class="stop-closed">${shape(false)}</g><g class="stop-release">${shape(true)}</g>`:shape(!stop),view,'mouth-svg',`${k}: ${stop?'língua fecha e solta atrás':hush?'ar contínuo com lábios projetados':'modelo de R inicial com passagem de ar'}`);
}
